static unsigned disconnects,meta_reads,meta_writes,reset_writes,csr_requests,copy_views;static uint16_t handles[2];static uint8_t metadata[8];static int mutate_second,persist_meta,return_wait;
static nc_flow native_hal(void *p,nc_model *n,const nc_request *r,nc_result *out){unsigned i;(void)p;CHECK(n==&m.native_callbacks);out->known=UINT32_MAX;out->value=0;
    if(r->kind==NC_ROM_DISCONNECT){CHECK(r->slot==380&&r->target==0x4017c&&r->count==1);CHECK(disconnects<2);if(disconnects<2)handles[disconnects++]=(uint16_t)r->arguments[0];if(mutate_second&&disconnects==1)put(A(0x40a2),9,2);out->known=0;return NC_RETURNED;}
    if(r->kind==NC_MMIO_READ){out->value=r->target==0x40013008?3u:r->target==0x4001300c?128u:0u;return NC_RETURNED;}
    if(r->kind==NC_MMIO_WRITE){if(r->target==0xe000e048){CHECK(r->width==32&&r->arguments[0]==0xbeef0080);reset_writes++;}return NC_RETURNED;}
    if(r->kind==NC_CSR_CLEAR||r->kind==NC_CSR_SET){CHECK(r->target==0x800&&r->arguments[0]==136);csr_requests++;return NC_RETURNED;}
    if(r->kind==NC_ROM_SCALAR){CHECK(r->slot==124);return NC_RETURNED;}
    if(r->kind==NC_ROM_COPY){CHECK(r->slot==76&&r->destination==NC_VALUE_VIEW&&r->length==8);out->length=8;if(r->source==NC_ADDRESS){CHECK(r->source_address==0x08077b00);memcpy(out->data,metadata,8);memset(out->bytes_known,255,8);meta_reads++;}else{CHECK(r->source==NC_VALUE_VIEW);memcpy(out->data,r->data,8);memcpy(out->bytes_known,r->known,8);copy_views++;}return NC_RETURNED;}
    if(r->kind==NC_FLASH_CALL){if(r->target==0x18c46){CHECK(r->count==1&&r->arguments[0]==0x08077b00);CHECK(r->source==NC_VALUE_VIEW&&r->length==256);CHECK(r->data[4]==1);for(i=0;i<8;i++)CHECK(r->known[i]==255);for(i=8;i<256;i++)CHECK(r->known[i]==0);if(persist_meta)memcpy(metadata,r->data,8);meta_writes++;}return NC_RETURNED;}
    if(r->kind==NC_JUMP){CHECK(r->target==0x8000&&r->count==1&&r->arguments[0]==0x12345678);return NC_TRANSFER;}
    if(r->kind==NC_RESET_WAIT)return return_wait?NC_RETURNED:NC_TRANSFER;
    return NC_HALT;
}
static rk_flow native_kernel_hal(void *p,rk_model *k,const rk_request *r,rk_result *out){(void)p;CHECK(k==&m.kernel);out->known=UINT32_MAX;out->value=0;if(r->kind==RK_MMIO_READ){out->value=0x7777;return RK_RETURNED;}if(r->kind==RK_MMIO_WRITE||r->kind==RK_FENCE_I)return RK_RETURNED;return RK_HALT;}
static void native_fresh(tc_image image){nc_backend b;rk_backend kb;fresh(image);memset(&b,0,sizeof(b));b.invoke=native_hal;ta_set_native_backend(&m,&b);memset(&kb,0,sizeof(kb));kb.invoke=native_kernel_hal;ta_set_kernel_backend(&m,&kb);disconnects=meta_reads=meta_writes=reset_writes=csr_requests=copy_views=0;memset(metadata,0,sizeof(metadata));metadata[1]=metadata[4]=2;mutate_second=persist_meta=return_wait=0;}
static void disconnect_live_handle(void){group("Runtime disconnect native body rereads second shared handle after first ROM380 returns");native_fresh(TC_RUNTIME);put(A(0x40a2),65534,2);mutate_second=1;CHECK(ta_dispatch_native(&m,0x8e12,0)==NC_RETURNED);CHECK(disconnects==2&&handles[0]==7&&handles[1]==9);CHECK(m.halted==0&&m.native_callbacks.memory==&m.memory);}
static void default_missing_and_sentinel(void){group("default source callback executes known sentinel branch, missing ROM primitive stops exact call");native_fresh(TC_BOOT);ta_set_native_backend(&m,NULL);put(A(0x407e),65534,2);CHECK(ta_dispatch_native(&m,0x192c,0)==NC_RETURNED);put(A(0x407e),7,2);CHECK(ta_dispatch_native(&m,0x192c,0)==NC_HALT);CHECK(m.halted==1&&m.native_callbacks.unknown_va==0x1940&&m.native_callbacks.unknown_address==0x4017c);}
static void boot_transfer(void){group("BOOT jump preserves raw a0 and reset wait requires known transfer");native_fresh(TC_BOOT);CHECK(ta_dispatch_native(&m,0x20e2,0x12345678)==NC_TRANSFER);CHECK(m.halted==1&&m.unresolved==0);native_fresh(TC_BOOT);CHECK(ta_dispatch_native(&m,0x1ff6,0)==NC_TRANSFER);CHECK(reset_writes==1&&csr_requests==1&&m.unresolved==0);native_fresh(TC_BOOT);return_wait=1;CHECK(ta_dispatch_native(&m,0x1ff6,0)==NC_HALT);CHECK(m.native_callbacks.unknown_va==0x200c&&m.halted==1);}
static void metadata_prefix_and_retry(void){group("Runtime boot request ports metadata retry/page masks then real GPIO SPI reset orchestration");native_fresh(TC_RUNTIME);persist_meta=1;CHECK(ta_dispatch_native(&m,0x9dfa,0)==NC_TRANSFER);CHECK(meta_reads==2&&meta_writes==1&&copy_views==1);CHECK(m.native_callbacks.metadata_status_known==1&&m.native_callbacks.metadata_status==0);CHECK(reset_writes==1&&csr_requests==3);native_fresh(TC_RUNTIME);CHECK(ta_dispatch_native(&m,0x9dfa,0)==NC_TRANSFER);CHECK(meta_reads==5&&meta_writes==5&&copy_views==5);CHECK(m.native_callbacks.metadata_status_known==1&&m.native_callbacks.metadata_status==1);CHECK(reset_writes==1&&csr_requests==11);}
static void system_source_routes(void){uint32_t pending;group("SystemProcess uses full native callback returned/transfer flow without unknown request observer");native_fresh(TC_RUNTIME);mutate_second=1;CHECK(tf_schedule(&m.memory,0x8e12,0,0,0)==0);CHECK(ta_system_process(&m)==RK_RETURNED);CHECK(disconnects==2&&get(TF_REGISTRY+4,4)==0&&get(A(0x304c),1)==4);native_fresh(TC_BOOT);CHECK(br_schedule(&m.boot,0x20e2,0,0,0x12345678)==0);pending=get(A(0x3094),4);CHECK(ta_system_process(&m)==RK_TRANSFER);CHECK(get(BR_REGISTRY+4,4)==0&&get(pending+6,2)==0);CHECK(get(A(0x304c),1)==3&&m.unresolved==0);}
int main(int argc,char **argv){FILE *f;unsigned i;if(argc!=3)return 2;f=fopen(argv[1],"rb");if(!f||fread(runtime,1,sizeof(runtime),f)!=sizeof(runtime)){if(f)fclose(f);return 2;}fclose(f);f=fopen(argv[2],"rb");if(!f||fread(boot,1,sizeof(boot),f)!=sizeof(boot)){if(f)fclose(f);return 2;}fclose(f);for(i=0;i<14;i++){uid[i]=(uint8_t)(17+i);known[i]=255;}uid[12]=uid[0];uid[13]=uid[1];disconnect_live_handle();default_missing_and_sentinel();boot_transfer();metadata_prefix_and_retry();system_source_routes();printf("NATIVE_BRIDGE_RESULT groups=%u checks=%u failures=%u original_executed=no hardware=no\n",groups,checks,failures);return failures?1:0;}
